impl super::Transform for presentation::SoundActionContent {
    fn transform(&self, ctx: &mut dyn officekit_markup::Context) -> Self {
        let node = super::ask(
            ctx.presentation(),
            presentation::Context::sound_action_content,
            self,
        );
        node.unwrap_or_else(|| self.transform_children(ctx))
    }

    fn transform_children(&self, ctx: &mut dyn officekit_markup::Context) -> Self {
        if let Self::Other(node) = self {
            Self::Other(node.transform(ctx))
        } else if let Self::StartSoundAction(arm) = self {
            Self::StartSoundAction(arm.transform(ctx))
        } else if let Self::StopSoundAction(arm) = self {
            Self::StopSoundAction(arm.transform(ctx))
        } else {
            self.clone()
        }
    }
}

